import re

# Function to extract bid price for 3.5% bond maturing Feb 1990
def extract_price(year):
    fname = f'/app/resources/treasury_bulletin_{year}_04_page_{89 if year==1972 else 91 if year==1973 else 88 if year>=1974 and year<=1975 else 104}.txt'
    if year == 1975:
        fname = '/app/resources/treasury_bulletin_1975_04_page_88.txt'
    elif year == 1976:
        fname = '/app/resources/treasury_bulletin_1976_04_page_104.txt'

    with open(fname, 'r') as f:
        content = f.read()

    # Find the row with 3-1/2 and 2/15/90
    pattern = r'3-1/2.*?2/15/90.*?td><td>([0-9]+\.[0-9]+)'
    match = re.search(pattern, content)
    if match:
        return match.group(1)
    return 'Not found'

for year in [1972, 1973, 1974, 1975, 1976]:
    print(f'{year}: {extract_price(year)}')
