import os

for year in [1972, 1973, 1974, 1975, 1976]:
    fname = f'/app/resources/treasury_bulletin_{year}_04.txt'
    with open(fname, 'r') as f:
        content = f.read()

    # Look for tables with exchange rates
    if ' Exchange ' in content:
        lines = content.split('\n')
        for i, line in enumerate(lines):
            if 'Country' in line and 'Currency' in line:
                print(f'{year}: Found at line {i}')
                for j in range(max(0, i-2), min(len(lines), i+10)):
                    if 'mark' in lines[j].lower() or 'dollar' in lines[j].lower():
                        print(f'  {j}: {lines[j][:100]}')
                break
