import json

for year in [1972, 1973, 1974, 1975]:
    fname = f'/app/resources/treasury_bulletin_{year}_04.json'
    try:
        with open(fname, 'r') as f:
            data = json.load(f)

        # Look for exchange rate or currency keys
        def search_dict(d, path=''):
            if isinstance(d, dict):
                for k, v in d.items():
                    if 'exchange' in k.lower() or 'rate' in k.lower() or 'currency' in k.lower():
                        print(f'{year}: {path}{k}')
                    search_dict(v, f'{path}{k}.')
            elif isinstance(d, list):
                for i, item in enumerate(d[:3]):  # Only check first few items
                    search_dict(item, f'{path}[{i}].')

        search_dict(data)
    except Exception as e:
        print(f'{year}: Error - {e}')
